"""conv2d_3x3 on the DRAM-interleaved path across activation layouts and dtypes (ROW_MAJOR bf16,
TILE bf16, TILE bf8_b), the fused ReLU, and C_in that is not a multiple of 32.

- layout matrix: every (dtype, layout) pair against the torch reference, with ReLU and bias on and off.
- NaN padding lanes: channels C_in..C_in_p of a pixel are padding (tile padding on TILE, DRAM page
  alignment on ROW_MAJOR) and sit against zero weight rows. The kernel never copies them into the
  im2col rows. The inputs here carry NaN in exactly those lanes. On Blackhole the matmul FPU returns
  0 for 0 x NaN / 0 x Inf, so these tests pin the output contract, not the lane exclusion itself.
- multi-M-block: a pinned one-tile-row M-block makes each core run several M-blocks, so state left by
  one block's epilogue (PACK_RELU, packer L1 accumulation) meets the next block's untilize and tilize.
"""

import os as _nsr_os
import sys as _nsr_sys

_nsr_sys.path.insert(
    0, "/localdev/pmilojevic/workspaces/opgen/ttnn/ttnn/operations/conv2d_3x3/perf_experiments/nslice_short_row"
)
from op_copies import copy_modules  # noqa: E402

_op_module, _pd = copy_modules(_nsr_os.environ.get("NSR_UT_PKG", "grad"))
import importlib

import pytest
import ttnn

from tests.ttnn.utils_for_testing import assert_with_pcc

conv2d_3x3 = _op_module.conv2d_3x3
prepare_conv2d_bias = _op_module.prepare_conv2d_bias
prepare_conv2d_weights = _op_module.prepare_conv2d_weights

_op_module = _op_module
_pd = _pd

# Golden-suite gates (eval/golden_tests/conv2d_3x3/helpers.py TOLERANCES), keyed by the coarser dtype.
PCC = {ttnn.bfloat16: 0.997, ttnn.bfloat8_b: 0.99}

LAYOUTS = [
    pytest.param(ttnn.bfloat16, ttnn.ROW_MAJOR_LAYOUT, id="rm_bf16"),
    pytest.param(ttnn.bfloat16, ttnn.TILE_LAYOUT, id="tile_bf16"),
    pytest.param(ttnn.bfloat8_b, ttnn.TILE_LAYOUT, id="tile_bf8b"),
]

# ((H, W, C_in), C_out, padding, stride, dilation)
SHAPES = [
    ((8, 8, 32), 32, 1, 1, 1),  # one core, one output tile
    ((16, 34, 32), 32, 0, 1, 1),  # valid padding, W_out != W
    ((16, 16, 8), 64, 1, 1, 1),  # C_in = 8: 24 padding lanes per pixel
    ((14, 16, 48), 64, 1, 1, 1),  # C_in = 48: lanes in the second channel tile
    ((32, 32, 8), 32, 1, 2, 1),  # stem-like: C_in = 8, stride 2
    ((32, 32, 64), 64, 2, 1, 2),  # dilated: per-tap gather
    ((16, 16, 32), 48, 1, 1, 1),  # C_out = 48: output tile padding
]


def _shape_id(case):
    (H, W, c_in), c_out, p, s, d = case
    return f"H{H}_W{W}_Ci{c_in}_Co{c_out}_p{p}_s{s}_d{d}"


def _reference(torch_input, torch_weight, torch_bias, case, relu):
    import torch

    (H, W, c_in), c_out, p, s, d = case
    x = torch_input.float().reshape(1, H, W, c_in).permute(0, 3, 1, 2)
    out = torch.nn.functional.conv2d(
        x, torch_weight.float(), None if torch_bias is None else torch_bias.float(), stride=s, padding=p, dilation=d
    )
    if relu:
        out = torch.relu(out)
    return out.permute(0, 2, 3, 1).reshape(1, 1, -1, c_out)


def _run(case, dtype, layout, weight_dtype, device, *, with_bias, relu, make_input=None):
    import torch

    (H, W, c_in), c_out, p, s, d = case
    torch_input = torch.randn(1, 1, H * W, c_in).to(torch.bfloat16)
    torch_weight = torch.randn(c_out, c_in, 3, 3).to(torch.bfloat16)
    torch_bias = torch.randn(c_out).to(torch.bfloat16) if with_bias else None
    kwargs = dict(
        stride=s,
        padding=p,
        dilation=d,
        input_dtype=dtype,
        input_layout=layout,
        weight_dtype=weight_dtype,
        input_memory_config=ttnn.DRAM_MEMORY_CONFIG,
        device=device,
    )
    tt_weight = prepare_conv2d_weights(torch_weight, **kwargs)
    tt_bias = prepare_conv2d_bias(torch_bias, **kwargs) if with_bias else None
    if make_input is None:
        tt_input = ttnn.from_torch(
            torch_input, dtype=dtype, layout=layout, device=device, memory_config=ttnn.DRAM_MEMORY_CONFIG
        )
    else:
        tt_input = make_input(torch_input)
    assert tt_input.layout == layout and tt_input.dtype == dtype

    tt_output = conv2d_3x3(
        tt_input,
        tt_weight,
        input_height=H,
        input_width=W,
        bias=tt_bias,
        padding=p,
        stride=s,
        dilation=d,
        activation="relu" if relu else None,
    )
    h_out = (H + 2 * p - 2 * d - 1) // s + 1
    w_out = (W + 2 * p - 2 * d - 1) // s + 1
    assert tt_output.layout == ttnn.TILE_LAYOUT
    assert tt_output.dtype == dtype
    assert list(tt_output.shape) == [1, 1, h_out * w_out, c_out]
    actual = ttnn.to_torch(tt_output).float()
    expected = _reference(torch_input, torch_weight, torch_bias, case, relu)
    assert torch.isfinite(actual).all(), f"{(~torch.isfinite(actual)).sum().item()} non-finite outputs"
    coarser = ttnn.bfloat8_b if ttnn.bfloat8_b in (dtype, weight_dtype) else ttnn.bfloat16
    assert_with_pcc(expected, actual, PCC[coarser])
    if relu:
        assert (actual >= 0).all(), "ReLU output holds negative values"


@pytest.mark.parametrize(
    "with_bias,relu", [(True, False), (True, True), (False, True)], ids=["bias", "bias_relu", "relu"]
)
@pytest.mark.parametrize("dtype,layout", LAYOUTS)
@pytest.mark.parametrize("case", SHAPES, ids=[_shape_id(c) for c in SHAPES])
def test_conv2d_3x3_layout_matrix(case, dtype, layout, with_bias, relu, device):
    import torch

    torch.manual_seed(42)
    _run(case, dtype, layout, ttnn.bfloat8_b, device, with_bias=with_bias, relu=relu)


# (dtype, C_in): a bf8_b NaN lane would share a 16-channel exponent group with real channels unless
# the lanes start a new group, so the bf8_b case uses C_in = 16.
NAN_TILE_CASES = [
    pytest.param(ttnn.bfloat16, 8, id="tile_bf16_Ci8"),
    pytest.param(ttnn.bfloat8_b, 16, id="tile_bf8b_Ci16"),
]


@pytest.mark.parametrize("dtype,c_in", NAN_TILE_CASES)
def test_conv2d_3x3_nan_tile_padding(dtype, c_in, device):
    import torch

    """TILE input whose tile padding (channels C_in..31) is NaN must give a finite, correct output."""
    torch.manual_seed(42)
    case = ((16, 16, c_in), 32, 1, 1, 1)

    def make_input(torch_input):
        return ttnn.from_torch(
            torch_input,
            dtype=dtype,
            layout=ttnn.TILE_LAYOUT,
            device=device,
            memory_config=ttnn.DRAM_MEMORY_CONFIG,
            pad_value=float("nan"),
        )

    _run(case, dtype, ttnn.TILE_LAYOUT, ttnn.bfloat16, device, with_bias=True, relu=False, make_input=make_input)


def test_conv2d_3x3_nan_row_major_page_padding(device):
    import torch

    """ROW_MAJOR C_in = 8 input written by a device op (an untilize of NaN-padded tiles), so its DRAM
    page padding is not rewritten by the host; the output must stay finite and correct."""
    torch.manual_seed(42)
    case = ((16, 16, 8), 32, 1, 1, 1)

    def make_input(torch_input):
        tiled = ttnn.from_torch(
            torch_input,
            dtype=ttnn.bfloat16,
            layout=ttnn.TILE_LAYOUT,
            device=device,
            memory_config=ttnn.DRAM_MEMORY_CONFIG,
            pad_value=float("nan"),
        )
        return ttnn.to_layout(tiled, ttnn.ROW_MAJOR_LAYOUT, memory_config=ttnn.DRAM_MEMORY_CONFIG)

    _run(
        case,
        ttnn.bfloat16,
        ttnn.ROW_MAJOR_LAYOUT,
        ttnn.bfloat16,
        device,
        with_bias=False,
        relu=False,
        make_input=make_input,
    )


MULTI_BLOCK_CASES = [
    pytest.param(ttnn.bfloat8_b, ttnn.TILE_LAYOUT, True, id="tile_bf8b_bias_relu"),
    pytest.param(ttnn.bfloat8_b, ttnn.TILE_LAYOUT, False, id="tile_bf8b_relu"),
    pytest.param(ttnn.bfloat16, ttnn.ROW_MAJOR_LAYOUT, False, id="rm_bf16_relu"),
]


@pytest.mark.parametrize("dtype,layout,with_bias", MULTI_BLOCK_CASES)
def test_conv2d_3x3_multi_m_block_relu(dtype, layout, with_bias, device, monkeypatch):
    import torch

    """Several M-blocks per core with ReLU: PACK_RELU must be off again before the next block's
    untilize and tilize (else negative activations are clamped), and on for every final pack."""
    torch.manual_seed(42)
    case = ((64, 128, 32), 32, 1, 1, 1)
    (H, W, c_in), c_out, p, s, d = case
    grid = device.compute_with_storage_grid_size()
    c_in_p = _op_module.per_pixel_channels(c_in, layout, ttnn.DRAM_MEMORY_CONFIG)
    geometry = _pd.Conv3x3Geometry(
        input_height=H,
        input_width=W,
        c_in_p=c_in_p,
        c_out=c_out,
        padding=p,
        stride=s,
        dilation=d,
        output_height=H,
        output_width=W,
        c_in=c_in,
        tile_input=layout == ttnn.TILE_LAYOUT,
        in0_tile_bytes=ttnn.tile_size(dtype),
        weight_tile_bytes=ttnn.tile_size(ttnn.bfloat16),
        out_tile_bytes=ttnn.tile_size(dtype),
        has_bias=with_bias,
    )
    core_m_tiles = -(-geometry.tensor_m_tiles // (grid.x * grid.y))
    assert core_m_tiles >= 2, "shape too small to give a core more than one M-block on this grid"
    # Pin one tile-row per M-block (the blocking an L1-bound shape would get) instead of tuning a budget
    # against the solver's search order.
    fit = _pd._footprint(geometry, core_m_tiles, 1, geometry.tensor_kkh_tiles, geometry.tensor_n_tiles)
    blocking = _pd.Conv3x3Blocking(
        grid_x=grid.x,
        core_m_tiles=core_m_tiles,
        num_m_groups=-(-geometry.tensor_m_tiles // core_m_tiles),
        block_m_tiles=1,
        block_k_tiles=geometry.tensor_kkh_tiles,
        block_n_tiles=geometry.tensor_n_tiles,
        out_depth_row_groups=_pd.OUT_DEPTH_ROW_GROUPS,
        **fit,
    )
    assert blocking.max_m_blocks_per_core > 1

    def pinned_blocking(g, grid_xy, l1_budget):
        assert g == geometry, "the test's geometry must match the op's"
        return blocking

    monkeypatch.setattr(_op_module, "select_blocking", pinned_blocking)

    _run(case, dtype, layout, ttnn.bfloat16, device, with_bias=with_bias, relu=True)
